public:
    bool checkZeroOnes(string s) {
        int max1 = 0, max0 = 0, c1 = 0, c0 = 0;
        for (char c : s) {
            if (c == '1') {
                c1++; c0 = 0;
            } else {
                c0++; c1 = 0;
            }
            max1 = max(max1, c1);
            max0 = max(max0, c0);
        }
        return max1 > max0;
    }
};

class Solution {
    public boolean checkZeroOnes(String s) {
        int max1 = 0, max0 = 0, c1 = 0, c0 = 0;
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (c == '1') {
                c1++; c0 = 0;
            } else {
                c0++; c1 = 0;
            }
            max1 = Math.max(max1, c1);
            max0 = Math.max(max0, c0);
        }
        return max1 > max0;
    }
}

/**
 * @param {string} s
 * @return {boolean}
